<?php
require_once 'config/db.php'; require_once 'config/auth.php'; require_login();
$page_title='Livestock Records'; $message=''; $error='';
$barangays=['Affecto','Balsahan','Bancaan','Bucana Malaki','Bucana Sasahan','Calubcob','Calayo','Capt. C. Nazareno','Gomez-Zamora','Hulugan','Ibayo Estacion','Ibayo Silangan','Latoria','Mabulo','Makina','Malainen Bago','Malainen Luma','Molino','Munting Mapino','Muzon','Palangue 1','Palangue 2','Palangue Central','Sabang','San Roque','Santulan','Sapa','Timalan Balsahan','Timalan Concepcion'];
if ($_SERVER['REQUEST_METHOD']==='POST') {
 $owner=trim($_POST['owner_name']??''); $phone=trim($_POST['phone']??''); $address=trim($_POST['address']??''); $barangay=trim($_POST['barangay']??''); $farm=trim($_POST['farm_name']??''); $type=$_POST['animal_type']??'Poultry'; $detail=trim($_POST['animal_detail']??''); $count=max(0,(int)($_POST['animal_count']??0)); $lat=($_POST['latitude']??'')!==''?$_POST['latitude']:null; $lng=($_POST['longitude']??'')!==''?$_POST['longitude']:null; $notes=trim($_POST['notes']??'');
 $allowed=['Poultry','Swine','Cattle','Goat','Carabao','Other'];
 if($owner===''||$farm===''||!in_array($barangay,$barangays,true)||!in_array($type,$allowed,true)||$count<1){$error='Please complete the required fields and enter an animal count of at least 1.';}
 elseif(($lat===null)!==($lng===null)||($lat!==null&&(!is_numeric($lat)||!is_numeric($lng)||abs((float)$lat)>90||abs((float)$lng)>180))){$error='Please select a valid map location.';}
 else { try{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO owners(owner_name,phone,address,barangay) VALUES(?,?,?,?)');$s->execute([$owner,$phone,$address,$barangay]);$oid=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO farms(owner_id,farm_name,animal_type,animal_detail,animal_count,barangay,latitude,longitude,notes) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$oid,$farm,$type,$detail,$count,$barangay,$lat,$lng,$notes]);$pdo->commit();$message='Owner and livestock record saved successfully.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not save the record. Please check the database settings and try again.';} }
}
$rows=$pdo->query('SELECT f.*,o.owner_name,o.phone FROM farms f JOIN owners o ON o.id=f.owner_id ORDER BY f.created_at DESC')->fetchAll();
include 'partials/header.php';
?>
<?php if($message):?><div class="alert success"><?=h($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?>
<section class="panel"><div class="panel-head"><h3>Add Poultry / Livestock Owner and Farm</h3></div><form method="post"><div class="form-grid"><div><label>Owner full name *</label><input name="owner_name" required placeholder="Owner name"></div><div><label>Contact number</label><input name="phone" placeholder="09XXXXXXXXX"></div><div class="wide"><label>Owner address</label><input name="address" placeholder="House no. / street / sitio"></div><div><label>Barangay *</label><select name="barangay" required><option value="">Select barangay</option><?php foreach($barangays as $b):?><option value="<?=h($b)?>"><?=h($b)?></option><?php endforeach;?></select></div><div><label>Farm / Poultry name *</label><input name="farm_name" required placeholder="Farm name"></div><div><label>Animal type *</label><select name="animal_type"><option>Poultry</option><option>Swine</option><option>Cattle</option><option>Goat</option><option>Carabao</option><option>Other</option></select></div><div><label>Animal details</label><input name="animal_detail" placeholder="Broiler, layer, native chicken"></div><div><label>Number of animals *</label><input type="number" name="animal_count" min="1" required></div><div class="wide"><label>Farm notes</label><textarea name="notes" placeholder="Optional details"></textarea></div><div><label>Latitude</label><input id="latitude" name="latitude" readonly placeholder="Click farm location on map"></div><div><label>Longitude</label><input id="longitude" name="longitude" readonly placeholder="Click farm location on map"></div><div class="wide"><p class="map-help">Click the map to pin the farm's location.</p><div id="pickMap" class="map"></div></div></div><button class="btn primary" type="submit">Save owner and farm</button></form></section>
<section class="panel"><div class="panel-head"><h3>All livestock / poultry records</h3><span class="muted"><?=count($rows)?> records</span></div><div class="table-wrap"><table><thead><tr><th>Owner</th><th>Farm</th><th>Animal type</th><th>Count</th><th>Barangay</th><th>Map pin</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['owner_name'])?></td><td><?=h($r['farm_name'])?></td><td><?=h($r['animal_type'])?> <?=h($r['animal_detail'])?></td><td><?=$r['animal_count']?></td><td><?=h($r['barangay'])?></td><td><?=($r['latitude']!==null&&$r['longitude']!==null)?'Pinned':'Not set'?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">No livestock records yet.</td></tr><?php endif;?></tbody></table></div></section>
<script src="assets/js/farm-picker.js"></script>
<?php include 'partials/footer.php'; ?>
